# -*- coding: utf-8 -*-
import math

# 获取所有小于等于100的质数
def get_primes():
    primes = []
    is_prime = [True] * 101
    for i in range(2, 101):
        if is_prime[i]:
            primes.append(i)
            for j in range(i * i, 101, i):
                is_prime[j] = False
    return primes

def main():
    n = int(input().strip())
    a = list(map(int, input().split()))

    primes = get_primes()  # 所有质数
    pCount = len(primes)

    # 对每个数计算质因数分解模2的表示，使用位掩码存储
    masks = [0] * n
    for i in range(n):
        x = a[i]
        cur_mask = 0
        for j in range(pCount):
            cnt = 0
            while x % primes[j] == 0:
                cnt += 1
                x //= primes[j]
            # 如果指数为奇数，则设置对应位为1
            if cnt % 2 == 1:
                cur_mask |= (1 << j)
        masks[i] = cur_mask

    ans = 0
    total = 1 << n  # 总共2^n种子集
    # 枚举所有非空子集
    for s in range(1, total):
        xor_sum = 0
        for i in range(n):
            if s & (1 << i):
                xor_sum ^= masks[i]
        # 如果异或结果为0，说明乘积为完全平方数
        if xor_sum == 0:
            ans += 1
    print(ans)

if __name__ == "__main__":
    main()
